-- Learning v2 isolated schema. Never execute against the legacy source database.
CREATE TABLE IF NOT EXISTS users (id CHAR(36) PRIMARY KEY, login_key VARCHAR(255) NULL UNIQUE, password_salt CHAR(32) NULL, password_hash CHAR(64) NULL, display_name VARCHAR(64) NULL, profile_json JSON NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS user_sessions (token_hash CHAR(64) PRIMARY KEY, user_id CHAR(36) NOT NULL, expires_at DATETIME(6) NOT NULL, INDEX(user_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS courses (id VARCHAR(40) PRIMARY KEY, name VARCHAR(160) NOT NULL, icon VARCHAR(255) NOT NULL DEFAULT '', description TEXT NOT NULL, level VARCHAR(40) NOT NULL, duration INT NOT NULL, chapters_json JSON NOT NULL, source_label VARCHAR(100) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS lessons (course_id VARCHAR(40) NOT NULL, lesson_index INT NOT NULL, title VARCHAR(200) NOT NULL, content_json JSON NOT NULL, quiz_json JSON NOT NULL, sources_json JSON NOT NULL, PRIMARY KEY(course_id,lesson_index), FOREIGN KEY(course_id) REFERENCES courses(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS lesson_progress (user_id CHAR(36) NOT NULL, course_id VARCHAR(40) NOT NULL, lesson_index INT NOT NULL, is_read TINYINT NOT NULL DEFAULT 0, score INT NULL, completed TINYINT NOT NULL DEFAULT 0, updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(user_id,course_id,lesson_index), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(course_id,lesson_index) REFERENCES lessons(course_id,lesson_index)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS quiz_attempts (id VARCHAR(64) NOT NULL, user_id CHAR(36) NOT NULL, course_id VARCHAR(40) NOT NULL, lesson_index INT NOT NULL, answers_json JSON NOT NULL, score INT NOT NULL, duration_seconds INT NOT NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(user_id,id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(course_id,lesson_index) REFERENCES lessons(course_id,lesson_index)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS user_state (user_id CHAR(36) PRIMARY KEY, favorites_json JSON NOT NULL, bookmarks_json JSON NOT NULL, updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
